package greeter

import "strings"

// Slug 把 s 转成小写连字符形式：去掉首尾空白，内部连续空白折成一个 "-"。
func Slug(s string) string {
	return strings.Join(strings.Fields(strings.ToLower(s)), "-")
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	cases := []struct {
		in, want string
	}{
		{"Hello World", "hello-world"},
		{"  Hello World  ", "hello-world"},
		{"a   b", "a-b"},
	}
	for _, c := range cases {
		if got := Slug(c.in); got != c.want {
			t.Errorf("Slug(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

package greeter

import "strings"

// JoinSlug 对每个部分取 Slug，跳过空结果，再用 "/" 连接。
func JoinSlug(parts ...string) string {
	slugs := make([]string, 0, len(parts))
	for _, p := range parts {
		if s := Slug(p); s != "" {
			slugs = append(slugs, s)
		}
	}
	return strings.Join(slugs, "/")
}

package greeter

import "testing"

func TestJoinSlug(t *testing.T) {
	if got := JoinSlug("Hello World", "Big Day"); got != "hello-world/big-day" {
		t.Errorf("JoinSlug(Hello World, Big Day) = %q, want %q", got, "hello-world/big-day")
	}
	if got := JoinSlug("a", "", "b"); got != "a/b" {
		t.Errorf("JoinSlug(a, , b) = %q, want %q", got, "a/b")
	}
	if got := JoinSlug("a", "   ", "b"); got != "a/b" {
		t.Errorf("JoinSlug(a, blank, b) = %q, want %q", got, "a/b")
	}
}
